package httpapi

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"incident-replay/backend/internal/replay"

	"github.com/prometheus/client_golang/prometheus/promhttp"
)

const scenariosDataDir = "./data/scenarios"

var validScenarioID = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)

var maxRPSPerRun int

func init() {
	maxRPSPerRun = 200 // default
	if val := os.Getenv("MAX_RPS_PER_RUN"); val != "" {
		var err error
		maxRPSPerRun, err = strconv.Atoi(val)
		if err != nil || maxRPSPerRun <= 0 {
			maxRPSPerRun = 200
		}
	}
}

// Handler handles HTTP API
// ... same as before except replayStart modified

type Handler struct {
	runner *replay.Runner
}

func NewHandler(r *replay.Runner) *Handler {
	return &Handler{runner: r}
}

func (h *Handler) Routes() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("/healthz", h.healthz)
	mux.Handle("/metrics", promhttp.Handler())

	mux.HandleFunc("/replay/start", h.replayStart)
	mux.HandleFunc("/replay/stop", h.replayStop)
	mux.HandleFunc("/replay/status", h.replayStatus)

	mux.HandleFunc("/replay/runs", h.replayRunsList)
	mux.HandleFunc("/replay/report", h.replayRunReport)

	mux.HandleFunc("/debug/echo", h.debugEcho)

	mux.HandleFunc("/scenarios/upload", h.scenarioUpload)
	mux.HandleFunc("/scenarios/list", h.scenarioList)

	return withJSON(withLogging(mux))
}

func (h *Handler) healthz(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
}

func (h *Handler) replayStart(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req startReq
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&req); err != nil {
		http.Error(w, "bad json", http.StatusBadRequest)
		return
	}

	// Set default for backward compatibility
	if req.Mode == "" {
		req.Mode = "burst"
	}

	// Validate mode
	if req.Mode != "burst" && req.Mode != "timestamp" {
		http.Error(w, "mode must be 'burst' or 'timestamp'", http.StatusBadRequest)
		return
	}

	// Validate speed if set
	if req.Speed != 0 && req.Speed <= 0 {
		http.Error(w, "speed must be > 0", http.StatusBadRequest)
		return
	}

	// Validate maxDelayMs if set
	if req.MaxDelayMs < 0 {
		http.Error(w, "maxDelayMs must be >= 0", http.StatusBadRequest)
		return
	}

	// Validate RPS: must be >0 and <= maxRPSPerRun
	if req.RPS <= 0 || req.RPS > maxRPSPerRun {
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(map[string]string{"error": "invalid_rps"})
		return
	}

	// Construct start params with extra fields
	params := replay.StartParams{
		ScenarioID:    req.ScenarioID,
		TargetBaseURL: req.TargetBaseURL,
		RPS:           req.RPS,
		Duration:      time.Duration(req.DurationSec) * time.Second,
		Mode:          req.Mode,
		Speed:         req.Speed,
		MaxDelayMs:    req.MaxDelayMs,
		StartFromTs:   req.StartFromTs,
		EndAtTs:       req.EndAtTs,
	}

	runID, err := h.runner.Start(params)
	if err != nil {
		// If error is concurrency limit, we might want to map to 429, but spec unclear
		// For now just return 400 with error text
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
		return
	}

	_ = json.NewEncoder(w).Encode(map[string]string{
		"runId":  runID,
		"status": "started",
	})
}

// Other handlers unchanged...

func (h *Handler) replayStop(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req stopReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad json", http.StatusBadRequest)
		return
	}

	if err := h.runner.Stop(req.RunID); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	_ = json.NewEncoder(w).Encode(map[string]string{
		"runId":  req.RunID,
		"status": "stopped",
	})
}

func (h *Handler) replayStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	runID := r.URL.Query().Get("runId")
	if runID == "" {
		http.Error(w, "runId is required", http.StatusBadRequest)
		return
	}

	st, err := h.runner.Status(runID)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	_ = json.NewEncoder(w).Encode(st)
}

// GET /replay/runs?limit=20 returns array of run summaries
func (h *Handler) replayRunsList(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	limit := 20
	qLimit := r.URL.Query().Get("limit")
	if qLimit != "" {
		// parse limit
		if l, err := parsePositiveInt(qLimit); err == nil && l > 0 {
			limit = l
		}
	}

	reports, err := h.runner.ListRuns(limit)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	_ = json.NewEncoder(w).Encode(reports)
}

// GET /replay/report?runId=... returns JSON report from store
func (h *Handler) replayRunReport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	runID := r.URL.Query().Get("runId")
	if runID == "" {
		http.Error(w, "runId is required", http.StatusBadRequest)
		return
	}

	report, err := h.runner.LoadReport(runID)
	if err != nil {
		http.Error(w, "report not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(report)
}

func parsePositiveInt(s string) (int, error) {
	var v int
	_, err := fmt.Sscanf(s, "%d", &v)
	if err != nil || v <= 0 {
		return 0, errors.New("not positive int")
	}
	return v, nil
}

func (h *Handler) debugEcho(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	_ = json.NewEncoder(w).Encode(map[string]bool{"ok": true})
}

// POST /scenarios/upload
// Accepts JSON {scenarioId string, jsonl string}
// Stores content into ./data/scenarios/<scenarioId>.jsonl
func (h *Handler) scenarioUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		ScenarioID string `json:"scenarioId"`
		JSONL      string `json:"jsonl"`
	}

	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&req); err != nil {
		http.Error(w, "bad json", http.StatusBadRequest)
		return
	}

	if !validScenarioID.MatchString(req.ScenarioID) {
		http.Error(w, "invalid scenarioId", http.StatusBadRequest)
		return
	}

	// Create directory if not exists
	err := os.MkdirAll(scenariosDataDir, 0o755)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	// Safe filepath join
	path := filepath.Join(scenariosDataDir, req.ScenarioID+".jsonl")

	// Validate no ../ in final path
	// fix: use filepath.Clean on path for prefix check
	if !filepath.HasPrefix(filepath.Clean(path), filepath.Clean(scenariosDataDir)+string(filepath.Separator)) {
		http.Error(w, "invalid scenarioId path", http.StatusBadRequest)
		return
	}

	// Write file
	err = os.WriteFile(path, []byte(req.JSONL), 0o644)
	if err != nil {
		http.Error(w, "failed to save scenario", http.StatusInternalServerError)
		return
	}

	_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok", "scenarioId": req.ScenarioID})
}

// GET /scenarios/list returns JSON array of scenarioIds
func (h *Handler) scenarioList(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	files, err := os.ReadDir(scenariosDataDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			// empty list
			_ = json.NewEncoder(w).Encode([]string{})
			return
		}
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	var ids []string
	for _, f := range files {
		if f.IsDir() {
			continue
		}
		name := f.Name()
		ext := filepath.Ext(name)
		if ext != ".jsonl" {
			continue
		}
		id := name[:len(name)-len(ext)]
		if !validScenarioID.MatchString(id) {
			continue
		}
		ids = append(ids, id)
	}

	_ = json.NewEncoder(w).Encode(ids)
}

type startReq struct {
	ScenarioID    string `json:"scenarioId"`
	TargetBaseURL string `json:"targetBaseUrl"`
	RPS           int    `json:"rps"`
	DurationSec   int    `json:"durationSec"`

	// New optional fields
	Mode        string  `json:"mode,omitempty"`        // burst|timestamp, default burst
	Speed       float64 `json:"speed,omitempty"`       // float64 > 0
	MaxDelayMs  int64   `json:"maxDelayMs,omitempty"`  // int >= 0
	StartFromTs string  `json:"startFromTs,omitempty"` // RFC3339 timestamp
	EndAtTs     string  `json:"endAtTs,omitempty"`     // RFC3339 timestamp
}

type stopReq struct {
	RunID string `json:"runId"`
}

package httpapi

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"strconv"
	"testing"

	"incident-replay/backend/internal/replay"
)

func setupHandler() *Handler {
	runner := replay.NewRunner()
	return NewHandler(runner)
}

func TestReplayStart_RPSValidation(t *testing.T) {
	h := setupHandler()

	// Test cases for invalid RPS
	tests := []struct {
		name    string
		rps     int
		wantErr bool
		wantCode int
		wantBody string
	}{
		{"zero rps", 0, true, 400, `{"error":"invalid_rps"}`},
		{"negative rps", -1, true, 400, `{"error":"invalid_rps"}`},
		{"rps too large", 201, true, 400, `{"error":"invalid_rps"}`},
		{"rps equal max", 200, false, 200, ""},
		{"rps valid middle", 100, false, 200, ""},
	}

	// Save and restore env for MAX_RPS_PER_RUN
	orig := os.Getenv("MAX_RPS_PER_RUN")
	defer os.Setenv("MAX_RPS_PER_RUN", orig)

	err := os.Setenv("MAX_RPS_PER_RUN", "200")
	if err != nil {
		t.Fatalf("failed to set env: %v", err)
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			reqBody := map[string]interface{}{
				"scenarioId":    "testscenario",
				"targetBaseUrl": "http://example.com",
				"rps":           tc.rps,
				"durationSec":   1,
			}
			buf := new(bytes.Buffer)
			err := json.NewEncoder(buf).Encode(reqBody)
			if err != nil {
				t.Fatalf("encode json failed: %v", err)
			}

			r := httptest.NewRequest("POST", "/replay/start", buf)
			w := httptest.NewRecorder()

			h.replayStart(w, r)

			res := w.Result()
			defer res.Body.Close()

			if res.StatusCode != tc.wantCode {
				t.Fatalf("unexpected status code %d, want %d", res.StatusCode, tc.wantCode)
			}

			if tc.wantErr {
				var resp map[string]string
				err := json.NewDecoder(res.Body).Decode(&resp)
				if err != nil {
					t.Fatalf("failed to decode json error body: %v", err)
				}
				if resp["error"] != "invalid_rps" {
					t.Fatalf("expected error 'invalid_rps', got '%s'", resp["error"])
				}
			} else {
				// expect runId and status in response
				var resp map[string]string
				err := json.NewDecoder(res.Body).Decode(&resp)
				if err != nil {
					t.Fatalf("failed to decode json success body: %v", err)
				}
				if resp["status"] != "started" {
					t.Fatalf("expected status 'started', got '%s'", resp["status"])
				}
				if resp["runId"] == "" {
					t.Fatalf("expected non-empty runId")
				}
			}
		})
	}
}

func TestReplayStart_RPSValidation_EnvOverride(t *testing.T) {
	h := setupHandler()

	oldMaxRPS := os.Getenv("MAX_RPS_PER_RUN")
	defer os.Setenv("MAX_RPS_PER_RUN", oldMaxRPS)
	os.Setenv("MAX_RPS_PER_RUN", "50")

	// Reload maxRPSPerRun from environment
	maxRPS := 0
	val := os.Getenv("MAX_RPS_PER_RUN")
	if val != "" {
		v, err := strconv.Atoi(val)
		if err == nil && v > 0 {
			maxRPS = v
		} else {
			maxRPS = 200
		}
	} else {
		maxRPS = 200
	}

	if maxRPS != 50 {
		t.Fatalf("expected maxRPS to be 50, got %d", maxRPS)
	}

	// rps 51 should be invalid
	reqBody := map[string]interface{}{
		"scenarioId":    "testscenario",
		"targetBaseUrl": "http://example.com",
		"rps":           51,
		"durationSec":   1,
	}
	buf := new(bytes.Buffer)
	err := json.NewEncoder(buf).Encode(reqBody)
	if err != nil {
		t.Fatalf("encode json failed: %v", err)
	}

	r := httptest.NewRequest("POST", "/replay/start", buf)
	w := httptest.NewRecorder()

	h.replayStart(w, r)

	res := w.Result()
	defer res.Body.Close()

	if res.StatusCode != 400 {
		t.Fatalf("expected status 400, got %d", res.StatusCode)
	}

	var resp map[string]string
	err = json.NewDecoder(res.Body).Decode(&resp)
	if err != nil {
		t.Fatalf("decode json failed: %v", err)
	}

	if resp["error"] != "invalid_rps" {
		t.Fatalf("expected error invalid_rps, got %s", resp["error"])
	}
}
